App.boot({id:'godown',title:'Main Godown',noCtx:true,render(el){const {esc,icon,num,money,formGrid}=U,S=Store,db=S.db;
 el.innerHTML=`<div class="page-head"><div><p>Office-only. Receive stock into the main godown at office rate, then send to farms.</p></div><div class="row"><a class="btn secondary" href="transfers.html">${icon('truck')} Send to farm</a><button class="btn" id="add">${icon('plus')} Receive into godown</button></div></div>
 <div class="grid g4">${S.ITEMS.map((it,i)=>{const rec=db.receipts.filter(x=>x.item===it).reduce((s,x)=>s+x.qty,0),av=S.godownQty(it);return `<div class="card kpi ${['','gold','blue','red'][i]}"><div class="ic">${icon('box')}</div><div style="flex:1"><div class="lbl">${it} available</div><div class="val">${num(av)}</div><div class="sub">Rate ${money(S.rate(it))} • received ${num(rec)}</div><div class="bar"><i style="width:${rec?av/rec*100:0}%"></i></div></div></div>`}).join('')}</div>
 <div class="grid g2" style="margin-top:16px"><div class="card"><div class="card-head"><h3>Godown balances</h3></div><div id="b"></div></div><div class="card"><div class="card-head"><h3>Receipts into godown</h3></div><div id="r"></div></div></div>`;
 U.dataTable(document.getElementById('b'),{search:false,rows:S.ITEMS,columns:[{label:'Item',value:i=>i,html:i=>`<b>${i}</b>`},{label:'Received',num:1,value:i=>db.receipts.filter(x=>x.item===i).reduce((s,x)=>s+x.qty,0)},{label:'Sent to farms',num:1,value:i=>db.transfers.filter(x=>x.item===i).reduce((s,x)=>s+x.qty,0)},{label:'Available',num:1,value:i=>S.godownQty(i),html:i=>`<b>${num(S.godownQty(i))}</b>`}]});
 U.dataTable(document.getElementById('r'),{rows:[...db.receipts].reverse(),filters:[{label:'Item',options:S.ITEMS,get:x=>x.item}],emptyTitle:'No receipts yet',columns:[{label:'Date',value:x=>x.date},{label:'Item',value:x=>x.item},{label:'Qty',num:1,value:x=>x.qty,html:x=>num(x.qty)},{label:'Office rate',num:1,value:x=>x.rate,html:x=>money(x.rate)},{label:'Value',num:1,value:x=>x.qty*x.rate,html:x=>money(x.qty*x.rate)}]});
 document.getElementById('add').onclick=()=>U.modal({title:'Receive into main godown',submit:'Receive into godown',body:formGrid([{name:'Item',label:'Item',options:S.ITEMS},{name:'Quantity',label:'Quantity',type:'number',attrs:'min="0.01" step="0.01"'},{name:'Rate',label:'Office rate (Rs)',type:'number',attrs:'min="0" step="0.01"'}]),
  onSubmit:d=>{const qty=Number(d.Quantity),r=Number(d.Rate);if(qty<=0||r<0)throw Error('Invalid quantity or rate');db.receipts.push({id:U.uid(),item:d.Item,qty,rate:r,date:U.today()});S.log(`Godown received ${qty} ${d.Item} @ ${r}`);U.toast('Stock received into godown');App.refresh()}})}});
